/// Parse a numeric component, capping at `u64::MAX` for overflow safety.
fn parse_numeric(bytes: &[u8]) -> u64 {
    let mut val: u64 = 0;
    for &b in bytes {
        let digit = (b - b'0') as u64;
        val = match val.checked_mul(10).and_then(|v| v.checked_add(digit)) {
            Some(v) => v,
            None => return u64::MAX,
        };
    }
    val
}

